create extension if not exists pgcrypto;
create table if not exists phone_numbers (id uuid primary key default gen_random_uuid(), e164 text unique not null, country_code text not null default 'BR', ddd text, state text, line_type text, carrier_current text, carrier_original text, ported boolean, carrier_checked_at timestamptz, reputation_score numeric, report_count integer not null default 0, lookup_count bigint not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists phone_identity (id uuid primary key default gen_random_uuid(), phone_id uuid not null references phone_numbers(id) on delete cascade, display_name text, cpf_masked text, confidence_score numeric, source_type text, source_provider text, verified boolean not null default false, verified_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now(), constraint cpf_must_be_masked check (cpf_masked is null or cpf_masked like '%*%'));
create table if not exists phone_reports (id uuid primary key default gen_random_uuid(), phone_id uuid not null references phone_numbers(id) on delete cascade, user_id uuid, category text not null check(category in ('spam','telemarketing','golpe','cobranca','robocall','pesquisa','entrega','empresa','pessoal','confiavel','outros')), description text, created_at timestamptz not null default now());
create table if not exists phone_lookup_cache (id uuid primary key default gen_random_uuid(), phone_id uuid not null references phone_numbers(id) on delete cascade, provider text not null, lookup_type text not null, result_json jsonb not null, checked_at timestamptz not null default now(), expires_at timestamptz not null, unique(phone_id,provider,lookup_type));
create table if not exists lookups (id uuid primary key default gen_random_uuid(), user_id uuid, phone_id uuid references phone_numbers(id), lookup_type text not null default 'free', status text not null, created_at timestamptz not null default now());
create table if not exists credit_wallets (user_id uuid primary key, balance integer not null default 0 check(balance>=0), updated_at timestamptz not null default now());
create table if not exists credit_transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null, amount integer not null, type text not null, reference text, created_at timestamptz not null default now());
create table if not exists audit_logs (id uuid primary key default gen_random_uuid(), user_id uuid, action text not null, metadata jsonb, created_at timestamptz not null default now());
create index if not exists idx_phone_e164 on phone_numbers(e164); create index if not exists idx_reports_phone on phone_reports(phone_id); create index if not exists idx_lookups_phone on lookups(phone_id);
